recipes.code:
{
  "inputs": [
    {
      "id": "agent-key",
      "type": "promptString",
      "description": "Hex private key of a wallet funded with USDC on Base (or Solana/Polygon/Arbitrum/Monad/Stellar/Algorand). Unset = proof-of-work mode (free pure-CPU tools).",
      "password": true
    }
  ],
  "servers": {
    "agent402": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "agent402-mcp@0.12.4"
      ],
      "env": {
        "AGENT_KEY": "${input:agent-key}",
        "AGENT402_BUDGET": "<agent402-budget>",
        "AGENT402_MAX_PER_CALL": "<agent402-max-per-call>"
      }
    }
  }
}
